def main():
    data = sys.stdin.read().split()
    if not data:
        return

    v1 = int(data[0])
    v2 = int(data[1])
    t = int(data[2])
    d = int(data[3])

    path = 0

    for current_t in range(t, 0, -1):
        path += v1
        maxSpeed = v2 + d * (current_t - 2)

        if maxSpeed > v1:
            if v1 + d > maxSpeed:
                v1 = maxSpeed
            else:
                v1 += d
        elif maxSpeed < v1:
            if v1 - d < maxSpeed:
                v1 = maxSpeed
            else:
                v1 -= d

    print(path)

if __name__ == "__main__":
    main()

